import { type FC, useEffect, useMemo, useRef, useState } from 'react';
import { useIntl } from 'react-intl';

import { CalendarClock } from '@hexa-ui/icons2';
import { Alert, BasicContainer, CountryFlag, Tag } from 'components';
import { useLastDataRefresh } from 'contexts';
import { useDataRefreshForTab } from 'contexts/DataRefreshModal/useDataRefreshForTab';
import { usePageFilterApplied } from 'hooks';
import { InvestmentBreakdownContainer, PageTitle } from 'pages/components';
import { getSyncedVisibleColumns } from 'pages/components/InvestmentBreakdownContainer/components/InvestmentBreakdownTable';
import { StyledTooltip } from 'shared/Styles';

import { RESOURCE_ALLOCATION_MEDIA_PAGE_NAME } from '../../ResourceAllocationMedia';
import {
  buildTableCustomizationGroups,
  getAllColumnIdsFromGroups,
  TableCustomization,
} from './components/TableCustomization';
import type { TableCustomizationGroup } from './components/TableCustomization';
import { useKpiRequests } from './hooks/useKpiRequests';
import {
  StyledInvestmentBreakdownWrapper,
  StyledPageTitleRightContent,
  StyledUsaAlertWrapper,
} from './InvestmentBreakdown.styles';

export interface InvestmentBreakdownProps {
  dataTestId?: string;
}

export const InvestmentBreakdown: FC<InvestmentBreakdownProps> = ({
  dataTestId,
}) => {
  useDataRefreshForTab('Resource Allocation - Investment Breakdown');

  const { formatMessage } = useIntl();

  const { applied } = usePageFilterApplied(RESOURCE_ALLOCATION_MEDIA_PAGE_NAME);

  const { data, loading, error } = useKpiRequests();

  const { lastDataRefreshKpisFormated } = useLastDataRefresh();

  const lastDataRefresh = lastDataRefreshKpisFormated?.media;

  const [visibleColumns, setVisibleColumns] = useState<string[] | null>(null);
  const previousColumnIdsKeyRef = useRef<string | null>(null);
  const customizationGroupsRef = useRef<TableCustomizationGroup[]>([]);

  const countrySelected = applied?.country;

  const tableData = data?.investment_breakdown;

  const customizationGroups = useMemo(() => {
    if (data?.filter?.length || tableData?.header?.length) {
      const groups = buildTableCustomizationGroups(
        tableData ?? { header: [], rows: [] },
        data?.filter,
      );
      customizationGroupsRef.current = groups;
      return groups;
    }

    return customizationGroupsRef.current;
  }, [tableData, data?.filter]);

  const allColumnIds = useMemo(
    () => getAllColumnIdsFromGroups(customizationGroups),

    [customizationGroups],
  );

  const columnIdsKey = useMemo(() => allColumnIds.join('|'), [allColumnIds]);

  useEffect(() => {
    if (!columnIdsKey) return;

    const previousKey = previousColumnIdsKeyRef.current;
    previousColumnIdsKeyRef.current = columnIdsKey;

    setVisibleColumns((previous) => {
      if (previous === null) {
        return [...allColumnIds];
      }

      const validPrevious = previous.filter((id) => allColumnIds.includes(id));

      if (!previousKey) {
        return [...allColumnIds];
      }

      if (previousKey === columnIdsKey) {
        if (validPrevious.length !== previous.length) {
          return [...validPrevious];
        }

        return previous;
      }

      const previousAllIds = previousKey.split('|');
      const hadAllSelected =
        previous.length === previousAllIds.length &&
        previousAllIds.every((id) => previous.includes(id));

      if (hadAllSelected) {
        return [...allColumnIds];
      }

      return [...validPrevious];
    });
  }, [columnIdsKey, allColumnIds]);

  const syncedVisibleColumns = useMemo(
    () =>
      visibleColumns === null
        ? allColumnIds
        : getSyncedVisibleColumns(visibleColumns, allColumnIds),
    [allColumnIds, visibleColumns],
  );

  const tableCustomization = (
    <TableCustomization
      key={columnIdsKey || 'table-customization'}
      groups={customizationGroups}
      selectedValues={syncedVisibleColumns}
      onValueChange={setVisibleColumns}
      dataTestId={dataTestId ? `${dataTestId}-table-customization` : undefined}
    />
  );

  return (
    <StyledInvestmentBreakdownWrapper>
      <PageTitle
        title={formatMessage({
          id: 'ConnectionsCreativity.ResourceAllocationMedia.InvestmentBreakdownTab.title',
        })}
        tooltip={
          <StyledTooltip
            data-testid={
              dataTestId
                ? `${dataTestId}-investment-breakdown-tooltip`
                : undefined
            }
            size="small"
          >
            {formatMessage({
              id: 'ConnectionsCreativity.ResourceAllocationMedia.InvestmentBreakdownTab.tooltip',
            })}
          </StyledTooltip>
        }
        rightContent={
          <StyledPageTitleRightContent>
            <CountryFlag dataTestId={dataTestId} />
          </StyledPageTitleRightContent>
        }
        dataTestId="page-title"
      />

      {lastDataRefresh && (
        <Tag Icon={CalendarClock} text={`: ${lastDataRefresh}`} />
      )}

      <BasicContainer
        dataTestId={
          dataTestId ? `${dataTestId}-investment-breakdown` : undefined
        }
        layout={{
          border: 'small',

          background: '#f9f9f9',

          bodyPadding: true,
        }}
      >
        {countrySelected === 'USA' && (
          <StyledUsaAlertWrapper>
            <Alert
              dataTestId={
                dataTestId
                  ? `${dataTestId}-investment-breakdown-alert`
                  : undefined
              }
              type="warning"
              title={formatMessage({
                id: 'ConnectionsCreativity.ResourceAllocationMedia.InvestmentBreakdownTab.USA.alert.title',
              })}
              message={formatMessage({
                id: 'ConnectionsCreativity.ResourceAllocationMedia.InvestmentBreakdownTab.USA.alert.message',
              })}
            />
          </StyledUsaAlertWrapper>
        )}

        <div className="target">
          {error ? (
            <Alert
              dataTestId={
                dataTestId
                  ? `${dataTestId}-investment-breakdown-error`
                  : undefined
              }
              type="error"
              title={formatMessage({
                id: 'ConnectionsCreativity.ResourceAllocationMedia.InvestmentBreakdownTab.error.title',

                defaultMessage: 'Error loading data',
              })}
              message={error.message}
            />
          ) : (
            <InvestmentBreakdownContainer
              dataTestId={
                dataTestId
                  ? `${dataTestId}-investment-breakdown-container`
                  : undefined
              }
              data={tableData}
              loading={loading}
              visibleColumns={syncedVisibleColumns}
              allColumnIds={allColumnIds}
              tableCustomization={tableCustomization}
            />
          )}
        </div>
      </BasicContainer>
    </StyledInvestmentBreakdownWrapper>
  );
};
